// Revenue conversion fix: ensure checkout events trigger paidEvents increment
// This module hooks into the checkout completion flow and increments paidEvents counter

const fs = require('fs');
const path = require('path');

const REVENUE_FILE = path.join(__dirname, '..', 'data', 'revenue.json');

function incrementPaidEvents() {
  try {
    let data = { paidEvents: 0, runs: 0, errors: 0, leads: 0 };
    if (fs.existsSync(REVENUE_FILE)) {
      data = JSON.parse(fs.readFileSync(REVENUE_FILE, 'utf8'));
    }
    data.paidEvents = (data.paidEvents || 0) + 1;
    data.runs = (data.runs || 0) + 1;
    fs.writeFileSync(REVENUE_FILE, JSON.stringify(data, null, 2));
    console.log('Revenue conversion: paidEvents incremented to', data.paidEvents);
  } catch (err) {
    console.error('Revenue conversion error:', err.message);
  }
}

// Export for use in checkout completion handler
module.exports = { incrementPaidEvents };
